function logActivity(title,detail,team,kind,icon='✓'){
 data.activity=data.activity||[];
 data.activity.unshift({title,detail,team,kind,icon,tone:'green',when:new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})});
 data.activity=data.activity.slice(0,18);
 persist();
}
const badge=s=>{let map={production:['In production','blue'],sampling:['Sampling','gold'],shipped:['Shipped','green'],pending:['Pending','gold'],approved:['Approved','green'],revision:['Revision','red'],scheduled:['Scheduled','blue'],passed:['Passed','green'],attention:['Attention','red'],inside:['Checked in','green'],left:['Checked out','blue'],verified:['Verified','green'],complete:['Completed','green']};let [t,c]=map[s]||[s,'blue'];return `<span class="badge ${c}">${t}</span>`};
const stat=(label,value,meta,icon='▤',tone='',change='')=>`<div class="card stat"><div class="stat-top"><span class="stat-icon ${tone}">${icon}</span>${change?`<span class="change">${change}</span>`:''}</div><div class="label">${label}</div><div class="value">${value}</div><div class="meta">${meta}</div></div>`;
const head=(title,subtitle,actions='')=>`<div class="page-head"><div><div class="eyebrow">ENSA SOURCING · DEMONSTRATION</div><h1>${title}</h1><p>${subtitle}</p></div><div class="head-tools">${actions}</div></div>`;
const card=(title,sub,body,action='')=>`<section class="card"><div class="card-head"><div><h3>${title}</h3>${sub?`<p>${sub}</p>`:''}</div>${action}</div>${body}</section>`;
const roleSwitch=()=>`<button class="role-select-wrap role-switch-button" data-action="switch-user" aria-label="Switch user dashboard"><span class="switch-avatar">${ROLES[role].initials}</span><span class="switch-label"><small>ACTIVE USER · TAP TO SWITCH</small><b>${ROLES[role].name}</b></span><span class="switch-chevron">⌄</span></button>`;
const intro=(title,sub)=>head(title,sub,roleSwitch());
const actionBtn=(title,cmd,cls='')=>`<button class="button ${cls}" data-action="${cmd}">${title}</button>`;
const link=(label,dest)=>`<button class="text-button" data-page="${dest}">${label}</button>`;
const progress=n=>`<div class="progress"><span style="width:${n}%"></span></div><div class="progress-caption">${n}% completed</div>`;
function chart(){let line='M 0 148 C 35 132, 52 139, 82 118 S 137 109, 169 102 S 214 109, 245 72 S 300 80, 330 53 S 389 57, 421 31 S 483 49, 515 13';return `<div class="chart-pad"><svg viewBox="0 0 515 190" preserveAspectRatio="none" role="img" aria-label="Order revenue growth over six months"><defs><linearGradient id="fillRevenue" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#3db797" stop-opacity=".24"/><stop offset="1" stop-color="#3db797" stop-opacity=".015"/></linearGradient></defs>${[38,79,121,163].map(y=>`<path d="M0 ${y} H515" fill="none" stroke="#e7efed" stroke-dasharray="4 5"/>`).join('')}<path d="${line} L515 177 H0 Z" fill="url(#fillRevenue)"/><path d="${line}" stroke="#249d80" stroke-width="3.4" fill="none" stroke-linecap="round"/><circle cx="515" cy="13" r="5" fill="#249d80" stroke="white" stroke-width="3"/></svg><div class="axis-row"><span>Jun</span><span>Jul</span><span>Aug</span><span>Sep</span><span>Oct</span><span>Nov</span></div><div class="legend-row"><span><i class="dot"></i> Order value</span><span><i class="dot gold"></i> Target trajectory</span></div></div>`}
function donut(values=['48','29','15','8'],center='82%',caption='On track'){let nums=values.map(Number),total=nums.reduce((a,b)=>a+b,0)||1,r=57,c=2*Math.PI*r,acc=0,colors=['#218f77','#6aa6c9','#e7b668','#e6eaea'];let rings=nums.map((n,i)=>{let part=n/total*c;let el=`<circle class="ring" cx="90" cy="90" r="${r}" fill="none" stroke="${colors[i]}" stroke-width="17" stroke-dasharray="${part} ${c-part}" stroke-dashoffset="${-acc}"/>`;acc+=part;return el}).join('');return `<svg class="donut" viewBox="0 0 180 180" role="img" aria-label="Donut breakdown"><circle cx="90" cy="90" r="57" fill="none" stroke="#eff3f1" stroke-width="17"/>${rings}<text x="90" y="88" text-anchor="middle" class="donut-center">${center}</text><text x="90" y="106" text-anchor="middle" class="donut-sub">${caption}</text></svg>`}
const distribution=(labels,nums,center='82%',caption='On track')=>`<div class="donut-wrap">${donut(nums,center,caption)}<div class="donut-labels">${labels.map((l,i)=>`<div class="item"><span><i class="dot ${['','blue','gold',''][i]}"></i>${l}</span><b>${nums[i]}%</b></div>`).join('')}</div></div>`;
const activity=(items)=>`<div class="activity">${items.map(([icon,title,description,time])=>`<div class="activity-item"><span class="activity-icon">${icon}</span><div><b>${title}</b><p>${description}</p><small>${time}</small></div></div>`).join('')}</div>`;
const tasks=(items)=>`<div class="task-list">${items.map(([icon,title,subtitle,cmd,button])=>`<div class="task-row"><span class="task-dot">${icon}</span><div class="task-main"><b>${title}</b><small>${subtitle}</small></div><button class="button sm" data-action="${cmd}">${button||'Review'}</button></div>`).join('')}</div>`;
const miniRows=items=>`<div class="mini-list">${items.map(([title,sub,right,detail])=>`<div class="mini-list-row"><div><b>${title}</b><small>${sub}</small></div><div class="right"><b>${right}</b><small>${detail}</small></div></div>`).join('')}</div>`;
const quick=(items)=>`<div class="quick-grid">${items.map(([icon,title,cmd])=>`<button class="quick-action" data-action="${cmd}"><span>${icon}</span>${title}</button>`).join('')}</div>`;
function orderRows(items){return `<div class="table-scroll"><table class="data-table"><thead><tr><th>Order / style</th><th>Buyer</th><th>Factory</th><th>Quantity</th><th>Stage</th><th>Progress</th><th>Target</th></tr></thead><tbody>${items.length?items.map(o=>`<tr data-id="${safe(o.id)}" data-kind="order"><td data-label="Order"><strong>${safe(o.id)}</strong><small>${safe(o.style)}</small></td><td data-label="Buyer">${safe(o.buyer)}</td><td data-label="Factory">${safe(o.factory)}</td><td data-label="Quantity">${fmt(o.qty)}</td><td data-label="Stage">${badge(o.status)}</td><td data-label="Progress">${progress(o.progress)}</td><td data-label="Target">${safe(o.due)}</td></tr>`).join(''):'<tr><td colspan="7"><div class="empty">No orders match these filters.</div></td></tr>'}</tbody></table></div>`}
const table=(headers,rows,kind='')=>`<div class="table-scroll"><table class="data-table"><thead><tr>${headers.map(s=>`<th>${s}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr ${kind?`data-kind="${kind}" data-id="${safe(r[0])}"`:''}>${r.map((v,i)=>`<td data-label="${safe(headers[i])}">${i===0?`<strong>${v}</strong>`:v}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}"><div class="empty">No records found</div></td></tr>`}</tbody></table></div>`;
function executive(){return intro('Executive dashboard','A clear, real-time picture of your sourcing business — all in one place.')+`<div class="hero"><div class="hero-text"><div class="hero-overline">BUSINESS HEALTH · NOVEMBER 2026</div><h2>Your operations are running strong.</h2><p>Most orders are progressing as expected. Two quality follow-ups and three pending approvals need management attention.</p></div><div class="hero-visual"><div class="hero-orb"><b>94.6%</b><small>On-time rate</small></div></div></div><div class="grid stats">${stat('Active buyer orders','32','Across 6 buying partners','▤','','+8.2%')}${stat('Order pipeline','$1.28M','Illustrative order value','৳','blue','+12.4%')}${stat('On-time delivery','94.6%','Above 92% target','◷','gold','+2.1%')}${stat('Action required','05','3 approvals · 2 QC issues','⚑','rose')}</div><div class="grid two-col">${card('Order performance','Monthly sourcing value and trend',chart(),`<button class="button sm" data-action="export">Export</button>`)}${card('Production health','Current workflow status',distribution(['On schedule','In sampling','At risk','Completed'],[64,20,9,7],'91%','Healthy'))}</div><div class="grid two-col">${card('Priority orders','Keep an eye on high-value and time-sensitive orders',orderRows(data.orders.slice(0,4)),link('All orders','orders'))}${card('Management attention','Only the items that need a decision',tasks([['◇','Buyer sample approvals','2 buyer decisions are outstanding','samples','Review'],['◎','QC verification required','Factory visit logged by Shaila Akter','attendance','Verify'],['▥','Monthly expense review','1 cost entry pending sign-off','finance','Review']]))}</div><div class="grid equal-col">${card('Factory performance','Illustrative compliance score',miniRows([['Apex Knitwear','Gazipur, Bangladesh','96%','On-track'],['Metro Apparels','Dhaka, Bangladesh','91%','On-track'],['Green Stitch Ltd.','Narayanganj','88%','Watchlist'],['Nova Garments','Dhaka, Bangladesh','85%','Needs follow-up']]),link('View partners','buyers'))}${card('Recent company activity','Latest cross-team updates',activity([['✓','Buyer approval received','Lab dip for H&M order EN-24081','18 minutes ago'],['◎','Factory QC report submitted','Metro Apparels visit notes uploaded','1 hour ago'],['▤','Production milestone updated','NEXT linen shirt reached 91%','Today, 09:45 AM']]))}</div>`}
function manager(){return intro('Operations control centre','Track orders, assign production work and resolve bottlenecks quickly.')+`<div class="hero"><div class="hero-text"><div class="hero-overline">TODAY'S OPERATIONS</div><h2>Keep production moving.</h2><p>6 orders need follow-up this week. Focus on pending samples, factory allocation and shipment readiness.</p></div><div class="hero-visual"><div class="hero-orb"><b>6</b><small>Follow-ups</small></div></div></div><div class="grid stats">${stat('Orders in production','24','Across 4 key factories','▤')}${stat('Due this week','06','Shipment milestones','◷','gold')}${stat('Merchandisers','08','Active assignments','♧','blue')}${stat('Pending samples','04','Review needed','◇','rose')}</div><div class="grid two-col">${card('Order delivery pipeline','Scheduled completion by week',chart())}${card('Next actions','Operational queue',tasks([['▤','Allocate a new order','Assign factory and merchandiser','new-order','Create'],['◇','Review sampling queue','2 unresolved sample decisions','samples'],['◎','Schedule factory inspection','Plan QC visit for Metro Apparels','new-qc','Schedule']]))}</div><div class="grid equal-col">${card('Production watchlist','Orders requiring close monitoring',orderRows(data.orders.filter(o=>o.progress<50).slice(0,3)),link('All orders','orders'))}${card('Merchandising workload','Assigned tasks by owner',miniRows([['Nadia Rahman','H&M · NEXT','8 orders','High activity'],['Arif Hasan','Zara','6 orders','Normal'],['Samira Chowdhury','Primark · C&A','7 orders','Normal']]),link('Assignments','merchandising'))}</div>`}
function merch(){let mine=data.orders.filter(o=>o.owner==='Nadia Rahman');return intro('My merchandising desk','Your orders, sampling decisions and factory milestones at a glance.')+`<div class="hero"><div class="hero-text"><div class="hero-overline">NADIA'S WORKSPACE</div><h2>Three priorities for today.</h2><p>Follow up on H&M shade approval, review the NEXT shipment timeline and update your factory progress notes.</p></div><div class="hero-visual"><div class="hero-orb"><b>3</b><small>Priorities</small></div></div></div><div class="grid stats">${stat('My orders',String(mine.length),'Current demo assignments','▤')}${stat('Awaiting buyer','02','Sample decisions','◇','gold')}${stat('On track','86%','Portfolio progress','◎','blue')}${stat('Due this week','01','NEXT shipment milestone','◷','rose')}</div><div class="grid two-col">${card('My orders','Assigned buyer orders',orderRows(mine),link('Order workspace','orders'))}${card('Today’s checklist','High priority merchandiser actions',tasks([['◇','Follow up on lab dip','H&M · EN-24081','samples','Open'],['▤','Update order progress','NEXT · EN-24084','orders','Open'],['◎','Review QC feedback','Apex Knitwear · EN-24081','quality','Open']]))}</div><div class="grid equal-col">${card('Sampling status','Buyer feedback progress',distribution(['Approved','Pending','Revision','Other'],[56,27,12,5],'56%','Approved'))}${card('Factory communication','Most recent notes',activity([['◈','Factory update requested','Apex Knitwear — bulk production status','Today, 10:15 AM'],['✓','Fit sample acknowledged','Zara sizing feedback logged','Yesterday'],['▤','Delivery plan confirmed','NEXT shipment target aligned','21 Nov']]))}</div>`}
function qcDashboard(){return intro('Quality control desk','Your inspections, factory visits and verification tasks.')+`<div class="hero"><div class="hero-text"><div class="hero-overline">INSPECTOR FIELD DESK</div><h2>Ready for today’s factory visits?</h2><p>Record inspection notes and GPS check-in at the factory. All visit records remain subject to management review.</p></div><div class="hero-visual"><div class="hero-orb"><b>2</b><small>Visits today</small></div></div></div><div class="grid stats">${stat('Today’s visits','02','Apex and Metro','◎')}${stat('QC pass rate','93%','Illustrative 30-day average','✓','blue')}${stat('Pending reports','01','Inspection notes due','▥','gold')}${stat('Issues flagged','01','Requires correction','⚑','rose')}</div><div class="grid two-col">${card('My inspection schedule','Upcoming visits and reports',table(['Inspection','Factory','Schedule','Result'],data.inspections.filter(x=>x.inspector==='Rafiq Ahmed').map(x=>[x.id,x.factory,x.date,badge(x.state)]),'qc'),link('Full QC module','quality'))}${card('Field actions','Timestamp and permission-based location concept',quick([['⌖','Factory check-in','checkin'],['▤','Submit QC report','qc-report'],['◎','View inspection plan','quality'],['◷','Attendance log','attendance']]))}</div><div class="grid equal-col">${card('Inspection quality','Recent outcome distribution',distribution(['Passed','Follow-up','Pending','Critical'],[72,14,10,4],'93%','Pass rate'))}${card('Latest field activity','QC-only activity',activity([['✓','Previous inspection passed','Green Stitch Ltd. · quality score 96','Yesterday'],['◎','Inspection scheduled','Metro Apparels for EN-24082','Today'],['◷','Location verified','Last field check-in was reviewed','22 Nov']]))}</div>`}
function hrDashboard(){return intro('People operations','Staff overview, leave approvals and payroll readiness.')+`<div class="grid stats">${stat('Total staff','42','Active employees','♧')}${stat('Office attendance','38 / 42','Today · ZKT concept','◷','blue')}${stat('Leave requests',String(data.leaves.filter(l=>l.state==='pending').length).padStart(2,'0'),'Waiting for approval','◇','gold')}${stat('Payroll status','Ready','November 2026 cycle','৳','rose')}</div><div class="grid two-col">${card('Attendance overview','Today’s employee presence',distribution(['Present','Absent','Leave','Late'],[83,7,7,3],'90%','Attendance'))}${card('Needs your review','Leave and payroll operations',tasks([['◇','Leave approval queue',`${data.leaves.filter(l=>l.state==='pending').length} employee requests`,'hr','Open'],['৳','Prepare November payroll','Monthly salary summaries','payroll','Review'],['◷','Check office attendance','ZKT-linked records in demo','attendance','Open']]))}</div><div class="grid equal-col">${card('Upcoming leave','Most recent requests',table(['Employee','Type','Dates','Status'],data.leaves.map(l=>[l.name,l.type,l.days,badge(l.state)])),link('Manage leave','hr'))}${card('HR quick actions','Employee operations',quick([['♧','Employee register','hr'],['◇','Request leave','new-leave'],['◷','Attendance','attendance'],['৳','Payroll preview','payroll']]))}</div>`}
function financeDashboard(){return intro('Finance overview','Track operational expenses and costs associated with buyer orders.')+`<div class="grid stats">${stat('Tracked order value','$1.28M','Demo sourcing pipeline','৳')}${stat('This month’s spend','৳ 842K','Illustrative expenses','▥','blue')}${stat('Expenses pending',String(data.expenses.filter(x=>x.state==='pending').length).padStart(2,'0'),'Awaiting approval','◷','gold')}${stat('Active cost centres','12','Order and office related','▦','rose')}</div><div class="grid two-col">${card('Expense trend','Spend distribution across recent months',chart())}${card('Expense allocation','Order-linked cost categories',distribution(['Samples','QC & travel','Office','Other'],[42,24,22,12],'76%','Order linked'))}</div><div class="grid equal-col">${card('Recent expenses','Items in the review queue',table(['Expense','Linked to','Amount','Status'],data.expenses.map(x=>[x.type,x.order,'৳ '+fmt(x.amount),badge(x.state)]),'expense'),link('Finance ledger','finance'))}${card('Finance actions','Keep spending and reporting organised',quick([['＋','Record expense','new-expense'],['▥','Finance ledger','finance'],['▤','Order costs','orders'],['⇩','Export report','export']]))}</div>`}
function receptionDashboard(){return intro('Front desk','A simple live view of visitors, appointments and arrivals.')+`<div class="hero"><div class="hero-text"><div class="hero-overline">RECEPTION · TODAY</div><h2>Welcome to Ensa Sourcing.</h2><p>Register incoming visitors, notify their hosts and capture check-out time in the visitor register.</p></div><div class="hero-visual"><div class="hero-orb"><b>${data.visitors.filter(v=>v.state==='inside').length}</b><small>Inside</small></div></div></div><div class="grid stats">${stat('Today’s visitors',String(data.visitors.length).padStart(2,'0'),'Recorded at front desk','♧')}${stat('Currently inside',String(data.visitors.filter(v=>v.state==='inside').length).padStart(2,'0'),'Waiting / in meetings','▣','blue')}${stat('Appointments','05','Planned for the day','◷','gold')}${stat('Completed visits',String(data.visitors.filter(v=>v.state==='left').length).padStart(2,'0'),'Checked out','✓','rose')}</div><div class="grid two-col">${card('Visitor register','Today’s arrivals',table(['Visitor','Company','Host','Status'],data.visitors.map(v=>[v.name,v.company,v.host,badge(v.state)]),'visitor'),link('Full visitor log','reception'))}${card('Fast check-in','Register guests in a few steps',quick([['＋','New visitor','new-visitor'],['▣','Visitor register','reception'],['✓','Check out visitor','reception'],['◷','Appointment list','reception']]))}</div>`}
function buyerDashboard(){
 const mine=data.orders.filter(o=>o.buyer==='H&M Group');
 const approvals=data.samples.filter(s=>s.buyer==='H&M Group'&&s.state==='pending');
 const avg=mine.length?Math.round(mine.reduce((a,o)=>a+o.progress,0)/mine.length):0;
 return intro('Welcome back, Olivia','Your orders, production progress and sample decisions in one private client view.')+
 `<div class="hero"><div class="hero-text"><div class="hero-overline">H&M GROUP · CLIENT PORTAL</div><h2>Your orders, clearly organised.</h2><p>View purchase orders, production progress and sample decisions in a focused client workspace.</p></div><div class="hero-visual"><div class="hero-orb"><b>${mine.length}</b><small>Your orders</small></div></div></div>`+
 `<div class="grid stats">${stat('Purchase orders',mine.length,'Visible to H&M Group','▤')}${stat('Production progress',avg+'%','Average across my orders','◎','blue')}${stat('Waiting for approval',approvals.length,'Buyer actions required','◇','gold')}${stat('Next delivery',mine[0]?.due||'—','Upcoming shipment target','◷','rose')}</div>`+
 `<div class="grid two-col">${card('My orders','Tap to view milestones and quantities',orderRows(mine),link('All my orders','orders'))}${card('Sample approval centre','Decisions only your buying team can make',approvals.length?tasks(approvals.map(s=>['◇',s.type+' · '+s.order,s.note,'samples','Review'])):`<div class="empty">No pending sample decisions.</div>`,link('Samples','samples'))}</div>`+
 `<div class="grid equal-col">${card('My production overview','Based on assigned purchase orders',distribution(['In production','Sampling','Shipped','Other'],[70,25,5,0],String(mine.length),'Orders'))}${card('Buyer notifications','Order and sample updates',activity([['◇','Lab dip awaiting your decision','Please review the colour sample','Today'],['▤','Production status updated','Essential Cotton Tee is progressing','Today'],['✓','Order milestone confirmed','Knit Lounge Set is in production','Yesterday']]))}</div>`;
}
function adminDashboard(){return intro('System administration','Manage users and visibility across the software demonstration.')+`<div class="grid stats">${stat('Registered users','58','Sample workspace members','♧')}${stat('Available roles','09','Role-based dashboards','⚙','blue')}${stat('Modules','12','Across five proposed phases','▦','gold')}${stat('System status','Demo','No live integrations','◎','rose')}</div><div class="grid two-col">${card('User roles','Preview the access model',miniRows(Object.values(ROLES).slice(0,7).map(r=>[r.name,r.caption,'Active','Role template'])),link('Permissions','team'))}${card('Administrator shortcuts','Workspace control centre',quick([['♧','Users & roles','team'],['▤','All orders','orders'],['▥','Reports','reports'],['⇩','Export demo','export']]))}</div>${roleCards()}`}
function roleCards(){return `<div class="role-strip">${Object.entries(ROLES).map(([k,r])=>`<button class="role-tile ${k===role?'selected':''}" data-role="${k}"><span>${r.icon}</span><b>${r.name}</b><p>${r.caption}</p>${k===role?'<small>Currently viewing</small>':''}</button>`).join('')}</div>`}
function ceoActivityEntries(){return [...(data.activity||[]), ...[
 {icon:'▤',team:'Merchandising',title:'Production milestone updated',detail:'Nadia updated H&M cotton tee to 78%.',when:'11:42 AM',kind:'orders',tone:'green'},
 {icon:'◎',team:'Quality control',title:'Factory inspection completed',detail:'Green Stitch passed with a 96% inspection score.',when:'11:18 AM',kind:'quality',tone:'blue'},
 {icon:'◇',team:'Buyer approvals',title:'Sample awaiting decision',detail:'Zara fit sample has been sent for buyer review.',when:'10:51 AM',kind:'samples',tone:'gold'},
 {icon:'◷',team:'Factory attendance',title:'QC inspector checked in',detail:'Rafiq recorded a factory visit at Apex Knitwear.',when:'10:05 AM',kind:'attendance',tone:'blue'},
 {icon:'৳',team:'Finance',title:'Expense approval requested',detail:'Local transport expense of ৳8,400 needs review.',when:'09:48 AM',kind:'finance',tone:'gold'},
 {icon:'♙',team:'Human resources',title:'Leave request submitted',detail:'Arif requested casual leave for 27–28 November.',when:'09:30 AM',kind:'hr',tone:'gold'},
 {icon:'▣',team:'Reception',title:'Visitor registered',detail:'Daniel James arrived for a management meeting.',when:'09:35 AM',kind:'reception',tone:'green'},
 {icon:'▤',team:'Order management',title:'New factory placement',detail:'EN-24087 was assigned to Nova Garments.',when:'Yesterday',kind:'orders',tone:'green'}
 ]]}
function ceoFeed(limit=8){return `<div class="ceo-feed">${ceoActivityEntries().slice(0,limit).map((e,i)=>`<button class="feed-event" data-page="${e.kind}"><span class="feed-track"><i class="feed-icon ${e.tone}">${e.icon}</i></span><span class="feed-body"><span class="feed-meta"><b>${e.team}</b><time>${e.when}</time></span><strong>${e.title}</strong><span class="feed-desc">${e.detail}</span></span><span class="feed-more">›</span></button>`).join('')}</div>`}
function ceoDashboard(){return intro('CEO overview','Every important company activity, decision and operational risk in one place.')+
 `<div class="ceo-banner"><div><div class="eyebrow">TUESDAY · 24 NOVEMBER 2026</div><h2>Good morning, Mahmud.</h2><p>Your team is moving 32 sourcing orders. Here is what needs your attention today.</p></div><button class="button" data-action="activity">View activity</button></div>`+
 `<div class="grid stats ceo-stats">${stat('Live orders','32','Across all buying partners','▤')}${stat('Pipeline value','$1.28M','Sample order portfolio','৳','blue')}${stat('Delivery health','94.6%','On-time target','◷','gold')}${stat('CEO decisions','05','2 QC · 3 approvals','⚑','rose')}</div>`+
 `<div class="grid two-col ceo-primary">${card('Company activity','Everything happening across departments',ceoFeed(),link('Full activity','dashboard'))}${card('Requires your attention','Decisions and approvals that need action',tasks([['⚑','Factory quality follow-up','Nova Garments · inspection score 71%','quality','Review'],['◇','Pending sample decisions','Buyer feedback needed for 2 samples','samples','Open'],['৳','Expense sign-off','One new expense for approval','finance','Review'],['◷','Field attendance verification','QC visit requires management confirmation','attendance','Verify']]))}</div>`+
 `<div class="grid equal-col">${card('Sourcing performance','Recent order value trend',chart())}${card('Production snapshot','Current workflow position',distribution(['On schedule','Sampling','At risk','Completed'],[64,20,9,7],'91%','Healthy'))}</div>`+
 `<div class="grid equal-col">${card('Latest orders','Tap an order for the full detail',orderRows(data.orders.slice(0,3)),link('All orders','orders'))}${card('Department pulse','Key teams at a glance',miniRows([['Merchandising','8 assigned users','32','Open orders'],['Quality control','6 inspectors','2','Visits today'],['Human resources','42 staff','2','Leave decisions'],['Finance','Order-linked spending','1','Pending expense']]))}</div>`+
 `<h2 class="section-title">See what every team sees</h2>${roleCards()}`}
function dashboard(){return ({executive:ceoDashboard,manager,merch,qc:qcDashboard,hr:hrDashboard,finance:financeDashboard,reception:receptionDashboard,buyer:buyerDashboard,admin:adminDashboard}[role])()}
