function ordersPage(){let all=onlyBuyer(data.orders);let filtered=all.filter(o=>(`${o.id} ${o.style} ${o.buyer} ${o.factory} ${o.owner}`).toLowerCase().includes(search.toLowerCase())&&(filter==='all'||o.status===filter));return head(role==='buyer'?'My purchase orders':'Order management','Buyer orders, factory placement, ownership, production stages and status history.',role==='buyer'?'':actionBtn('+ Register order','new-order','primary'))+`<div class="grid stats">${stat('Visible orders',all.length,'Records in this workspace','▤')}${stat('In production',all.filter(o=>o.status==='production').length,'Currently with factories','◎','blue')}${stat('Sampling',all.filter(o=>o.status==='sampling').length,'Approval workflow','◇','gold')}${stat('Pieces ordered',fmt(all.reduce((a,o)=>a+o.qty,0)),'Across visible orders','▦','rose')}</div><div class="filters"><input id="searchOrders" class="search-field" placeholder="Search order, style, buyer or factory" value="${safe(search)}" aria-label="Search orders"><select class="filter-field" id="filterOrders" aria-label="Filter order stage">${[['all','All stages'],['production','In production'],['sampling','Sampling'],['shipped','Shipped']].map(([k,v])=>`<option value="${k}" ${filter===k?'selected':''}>${v}</option>`).join('')}</select><button class="button" data-action="export">Export CSV</button></div>${card('Production order register',`${filtered.length} matching orders · select a row for milestones`,orderRows(filtered))}<div class="callout"><div><strong>Connected order workflow</strong><p>Registration → Factory placement → Merchandiser assignment → Sample approval → QC → Shipment</p></div>${actionBtn('View samples','samples')}</div>`}
