function merchandisingPage(){return head('Merchandising workspace','Assignment overview and buyer coordination for sourcing teams.',actionBtn('+ New assignment','new-order','primary'))+`<div class="grid stats">${stat('Team members','08','Merchandisers','♙')}${stat('Active assignments','32','Open buyer orders','▤','blue')}${stat('Follow-ups this week','06','Need action','◷','gold')}${stat('Sampling requests','14','Across teams','◇','rose')}</div><div class="grid equal-col">${card('Workload by merchandiser','Top active owners',miniRows([['Nadia Rahman','H&M Group · NEXT','8 orders','3 follow-ups'],['Arif Hasan','Zara','6 orders','2 follow-ups'],['Samira Chowdhury','Primark · C&A','7 orders','1 follow-up'],['Tanvir Ahmed','Mango','5 orders','On track']]))}${card('Assignment progress','Illustrative work distribution',distribution(['In production','Sampling','Finishing','Shipped'],[58,21,14,7],'32','Orders'))}</div>${card('Recently assigned orders','Select any row for the order detail',orderRows(data.orders.slice(0,5)))}`}
function samplesPage(){
 const arr=onlyBuyer(data.samples),count=s=>arr.filter(x=>x.state===s).length,total=Math.max(1,arr.length);
 const counts=[count('approved'),count('pending'),count('revision'),arr.filter(x=>!['approved','pending','revision'].includes(x.state)).length];
 const shares=counts.map(x=>Math.round(x/total*100));
 return head(role==='buyer'?'My sample approvals':'Sample approvals',role==='buyer'?'Review only samples assigned to your buying team.':'Submit, review and resolve lab dips, fit samples and pre-production requests.',role==='buyer'?'':actionBtn('+ Request sample','new-sample','primary'))+
 `<div class="grid stats">${stat('Sample requests',arr.length,'Visible requests','◇')}${stat('Awaiting review',count('pending'),'Need buyer response','◷','gold')}${stat('Approved',count('approved'),'Ready to proceed','✓','blue')}${stat('Revisions',count('revision'),'Changes requested','▤','rose')}</div>`+
 `<div class="grid equal-col">${card('Approval pipeline','Based on current demo records',distribution(['Approved','Pending','Revision','Other'],shares,shares[0]+'%','Approved'))}${card('Review workflow','The steps for each buyer sample',activity([['1','Sample requested','Merchandiser registers the sample type','Request'],['2','Buyer review','Approve or request changes','Decision'],['3','Status recorded','Decision is linked to the order','Complete']]))}</div>`+
 card('Approval requests','Tap a record to open the approval modal',table(['Sample / order','Buyer','Type','Submitted','Status'],arr.map(x=>[`${x.id} · ${x.order}`,x.buyer,x.type,x.date,badge(x.state)]),'sample'));
}
