function receptionPage(){return head('Reception & visitor log','Guest registration, host notifications and check-out records.',actionBtn('+ Check in visitor','new-visitor','primary'))+`<div class="grid stats">${stat('Visitors registered',data.visitors.length,'Today','♧')}${stat('Currently inside',data.visitors.filter(x=>x.state==='inside').length,'On the premises','▣','blue')}${stat('Completed visits',data.visitors.filter(x=>x.state==='left').length,'Checked out','✓','gold')}${stat('Meetings scheduled','05','Demo appointments','◷','rose')}</div><div class="grid two-col">${card('Today’s visitor register','Select checked-in guests to check them out',table(['Visitor','Company','Host','Arrived','Status'],data.visitors.map(x=>[x.name,x.company,x.host,x.time,badge(x.state)]),'visitor'))}${card('Front desk actions','Simple reception operations',quick([['＋','Register guest','new-visitor'],['▣','View all visitors','reception'],['◷','Appointments','appointments'],['⇩','Export visitor log','export']]))}</div>`}
function financePage(){return head('Basic finance management','Track income, expenses, order-linked costs and management reports.',actionBtn('+ Record expense','new-expense','primary'))+`<div class="grid stats">${stat('Order value','$1.28M','Illustrative buyer value','৳')}${stat('Tracked expenses','৳ '+fmt(data.expenses.reduce((a,x)=>a+x.amount,0)),'Demo expense entries','▥','blue')}${stat('Pending approval',data.expenses.filter(x=>x.state==='pending').length,'Require review','◇','gold')}${stat('Cost centres','12','Orders and operations','▦','rose')}</div><div class="grid equal-col">${card('Expense allocation','Illustrative category split',distribution(['Sampling','QC & travel','Office','Other'],[42,24,22,12],'76%','Order-linked'))}${card('Finance trend','Monthly operational movement',chart())}</div>${card('Expense ledger','Select a record to review',table(['Reference','Expense','Order link','Amount','Status'],data.expenses.map(x=>[x.id,x.type,x.order,'৳ '+fmt(x.amount),badge(x.state)]),'expense'))}`}
function reportsPage(){return head('Reports & insights','A concise management reporting centre, using mock operational data.',actionBtn('Export CSV','export','primary'))+`<div class="grid stats">${stat('Order portfolio','$1.28M','Illustrative value','▤')}${stat('Production healthy','91%','Current workflow','◎','blue')}${stat('Factory pass rate','93%','QC record sample','✓','gold')}${stat('Office attendance','90.5%','ZKT demo','◷','rose')}</div><div class="grid equal-col">${card('Order value trend','Production and sales reporting',chart())}${card('Order mix','Stage mix snapshot',distribution(['Production','Sampling','Shipped','Other'],[64,22,9,5],'32','Orders'))}</div><div class="grid three-col">${card('Orders report','Export pipeline details',`<div class="mini-list"><div class="mini-list-row"><div><b>Current order register</b><small>Buyer · factory · status · shipment</small></div></div></div>`,actionBtn('Download','export','sm'))}${card('QC report','Inspection summary',`<div class="mini-list"><div class="mini-list-row"><div><b>Factory scorecards</b><small>Inspection status and score</small></div></div></div>`,actionBtn('View QC','quality','sm'))}${card('Finance report','Cost breakdown',`<div class="mini-list"><div class="mini-list-row"><div><b>Expense categorisation</b><small>Order linked vs overhead</small></div></div></div>`,actionBtn('View ledger','finance','sm'))}</div>`}
