const VIEWS={dashboard,orders:ordersPage,buyers:buyersPage,merchandising:merchandisingPage,samples:samplesPage,quality:qualityPage,attendance:attendancePage,hr:hrPage,reception:receptionPage,finance:financePage,reports:reportsPage,team:teamPage};
function renderNav(){const n=ROLES[role].nav;n.forEach(k=>{});$('#nav').innerHTML=n.map((k,i)=>`${i===0?'':i===1?'<div class="nav-group">MANAGEMENT</div>':''}<button class="nav-item ${page===k?'active':''}" data-page="${k}"><span class="ni">${PAGES[k][1]}</span>${PAGES[k][0]}${k==='samples'&&role!=='buyer'?'<span class="pill-num">4</span>':''}</button>`).join('')}
function render(){if(!ROLES[role].nav.includes(page))page='dashboard';renderNav();let r=ROLES[role];$('#main').innerHTML=VIEWS[page]();$('#sideUser').textContent=$('#topUser').textContent=r.user;$('#sideRole').textContent=$('#topRole').textContent=r.name;$('#sideAvatar').textContent=$('#topAvatar').textContent=r.initials;$('#crumbTitle').textContent=page==='dashboard'?r.name+' dashboard':PAGES[page][0];document.title=(page==='dashboard'?r.name+' dashboard':PAGES[page][0])+' · Ensa Software';closeMenu()}
function go(p){if(ROLES[role].nav.includes(p)){$('#modal').innerHTML='';page=p;search='';filter='all';render();window.scrollTo({top:0,behavior:'smooth'})}else toast('This module is outside the selected role’s workspace.')}
function switchRole(next){if(!ROLES[next])return;role=next;localStorage.setItem('ensa-v2-role',next);$('#modal').innerHTML='';page='dashboard';tab='all';render();window.scrollTo({top:0,behavior:'smooth'});toast(`Switched to ${ROLES[role].name} dashboard`)}
function toast(t){const x=$('#toast');x.textContent=t;x.classList.add('show');clearTimeout(window.toastId);window.toastId=setTimeout(()=>x.classList.remove('show'),3600)}
function closeMenu(){$('#sidebar').classList.remove('open');$('#backdrop').classList.remove('visible')}
function modal(title,subtitle,body,footer=''){
 const replaceTerm=value=>String(value).replace(/\bERP\b/g,'Software');
 title=replaceTerm(title);subtitle=replaceTerm(subtitle);body=replaceTerm(body);footer=replaceTerm(footer);
 $('#modal').innerHTML=`<div class="modal-backdrop"><div class="modal-card" role="dialog" aria-modal="true" aria-label="${safe(title)}"><div class="modal-head"><div><h2>${title}</h2><p>${subtitle}</p></div><button class="close-x" data-action="close" aria-label="Close">×</button></div>${body}${footer}</div></div>`;
}
function formModal(type){const fields={
 'new-order':['Register a sourcing order','Create a buyer order and assign factory / merchandiser.',`<div class="field"><label>Buyer</label><select name="buyer"><option>H&M Group</option><option>Zara</option><option>Primark</option><option>NEXT</option><option>Mango</option><option>C&A</option></select></div><div class="field"><label>Style / product</label><input name="style" required maxlength="80" placeholder="e.g. Cotton Polo"></div><div class="field"><label>Factory placement</label><select name="factory"><option>Apex Knitwear</option><option>Metro Apparels</option><option>Green Stitch Ltd.</option><option>Nova Garments</option></select></div><div class="field"><label>Quantity (pieces)</label><input name="qty" type="number" required min="1" max="9999999" placeholder="12000"></div><div class="field"><label>Merchandiser</label><select name="owner"><option>Nadia Rahman</option><option>Arif Hasan</option><option>Samira Chowdhury</option><option>Tanvir Ahmed</option></select></div><div class="field"><label>Target delivery date</label><input name="due" type="date" required></div>`],
 'new-sample':['Request a sample','Send a new review request into the mock approval queue.',`<div class="field"><label>Order</label><select name="order">${data.orders.map(o=>`<option value="${o.id}">${o.id}</option>`).join('')}</select></div><div class="field"><label>Sample type</label><select name="type"><option>Lab dip</option><option>Fit sample</option><option>Size set</option><option>Pre-production</option></select></div><div class="field full"><label>Review notes</label><textarea name="note" rows="3" placeholder="Buyer feedback or requirements"></textarea></div>`],
 'new-qc':['Schedule an inspection','Assign a factory visit and inspection owner.',`<div class="field"><label>Factory</label><select name="factory"><option>Apex Knitwear</option><option>Metro Apparels</option><option>Green Stitch Ltd.</option><option>Nova Garments</option></select></div><div class="field"><label>Order</label><select name="order">${data.orders.map(o=>`<option value="${o.id}">${o.id}</option>`).join('')}</select></div><div class="field"><label>Inspector</label><select name="inspector"><option>Rafiq Ahmed</option><option>Shaila Akter</option><option>Imran Kabir</option></select></div><div class="field"><label>Visit date</label><input name="date" type="date" required></div>`],
 'new-visitor':['Check in a visitor','Create a front desk entry with a host and arrival time.',`<div class="field"><label>Visitor name</label><input name="name" required placeholder="Full name"></div><div class="field"><label>Company</label><input name="company" required placeholder="Company / organisation"></div><div class="field full"><label>Person to meet</label><input name="host" required placeholder="Host or department"></div>`],
 'new-expense':['Record an expense','Connect an operational cost to an order or general overhead.',`<div class="field"><label>Expense category</label><select name="type"><option>Sample development</option><option>Factory inspection</option><option>Local transport</option><option>Office operations</option></select></div><div class="field"><label>Order / cost centre</label><select name="order"><option>General</option>${data.orders.map(o=>`<option>${o.id}</option>`).join('')}</select></div><div class="field full"><label>Amount (BDT)</label><input name="amount" required min="1" type="number" placeholder="2500"></div>`],
 'new-leave':['Leave request','Enter a request for a management decision.',`<div class="field"><label>Employee</label><select name="name"><option>Nadia Rahman</option><option>Arif Hasan</option><option>Shaila Akter</option><option>Mitu Akter</option></select></div><div class="field"><label>Leave type</label><select name="type"><option>Casual leave</option><option>Annual leave</option><option>Sick leave</option></select></div><div class="field full"><label>Dates</label><input name="days" required placeholder="e.g. 02–04 Dec"></div>`]
 };if(!fields[type])return;let [title,desc,inputs]=fields[type];modal(title,desc,`<form id="demoForm" data-type="${type}"><div class="form-grid">${inputs}</div><div class="modal-actions"><button class="button" type="button" data-action="close">Cancel</button><button class="button primary" type="submit">Save demo record</button></div></form>`) }
function detail(kind,id){
 const collection={order:'orders',sample:'samples',qc:'inspections',leave:'leaves',expense:'expenses',visitor:'visitors',checkin:'checkins'}[kind];
 if(!collection||!data[collection])return;
 const module={order:'orders',sample:'samples',qc:'quality',leave:'hr',expense:'finance',visitor:'reception',checkin:'attendance'}[kind];
 if(!ROLES[role].nav.includes(module))return toast('This record is not available for your role.');
 const x=data[collection].find(t=>kind==='sample'?`${t.id} · ${t.order}`===id||t.id===id:t.id===id);
 if(!x)return;
 if(role==='buyer'&&!((kind==='order'||kind==='sample')&&x.buyer==='H&M Group'))return toast('This record is not available in your client portal.');
 let body='',buttons='';
 if(kind==='order'){
  const fields=[['Buyer',x.buyer],['Factory',x.factory],['Style',x.style],['Merchandiser',x.owner],['Quantity',fmt(x.qty)+' pieces'],['Delivery target',x.due],['Stage',x.status],['Order value','$'+fmt(x.value||0)]];
  const stages=role==='buyer'?['Registered','Sample approval','In production','Shipment']:['Registered','Factory assigned','Sampling','Production','Quality control','Shipment'];
  const stageIndex=x.status==='shipped'?stages.length-1:x.status==='sampling'?(role==='buyer'?1:2):(role==='buyer'?2:3);
  const samples=data.samples.filter(s=>s.order===x.id);
  const inspections=role==='buyer'?[]:data.inspections.filter(q=>q.order===x.id);
  body=`<div class="order-progress-hero"><span>PRODUCTION COMPLETION</span><strong>${x.progress}%</strong>${progress(x.progress)}</div>
   <h3 class="modal-section-title">Milestone timeline</h3><div class="order-steps">${stages.map((s,i)=>`<div class="order-step ${i<=stageIndex?'done':''}"><span>${i<=stageIndex?'✓':i+1}</span><b>${s}</b></div>`).join('')}</div>
   <h3 class="modal-section-title">Order information</h3><div class="detail-grid">${fields.map(([k,v])=>`<div class="detail-cell"><small>${k}</small><strong>${safe(v)}</strong></div>`).join('')}</div>
   <h3 class="modal-section-title">Linked samples</h3><div class="linked-records">${samples.length?samples.map(s=>`<div><b>${safe(s.type)}</b>${badge(s.state)}</div>`).join(''):'<p>No sample records.</p>'}</div>
   ${role==='buyer'?'':`<h3 class="modal-section-title">Internal inspection history</h3><div class="linked-records">${inspections.length?inspections.map(q=>`<div><b>${safe(q.factory)}</b>${badge(q.state)}</div>`).join(''):'<p>No inspections assigned.</p>'}</div>`}`;
  if(allowed('advance'))buttons=`<button class="button primary" data-action="advance" data-id="${safe(x.id)}">Update production +10%</button>`;
 }else{
  body=`<div class="detail-grid">${Object.entries(x).filter(([k])=>k!=='id').map(([k,v])=>`<div class="detail-cell"><small>${safe(k.replace(/([A-Z])/g,' $1'))}</small><strong>${safe(v)}</strong></div>`).join('')}</div>`;
  if(kind==='sample'&&x.state==='pending'&&allowed('decision:sample'))buttons=`<button class="button" data-action="decision" data-value="revision" data-id="${safe(x.id)}" data-kind="sample">Request revision</button><button class="button primary" data-action="decision" data-value="approved" data-id="${safe(x.id)}" data-kind="sample">Approve sample</button>`;
  if(kind==='leave'&&x.state==='pending'&&allowed('decision:leave'))buttons=`<button class="button primary" data-action="decision" data-kind="leave" data-id="${safe(x.id)}" data-value="approved">Approve leave</button>`;
  if(kind==='expense'&&x.state==='pending'&&allowed('decision:expense'))buttons=`<button class="button primary" data-action="decision" data-kind="expense" data-id="${safe(x.id)}" data-value="approved">Approve expense</button>`;
  if(kind==='visitor'&&x.state==='inside'&&allowed('decision:visitor'))buttons=`<button class="button primary" data-action="decision" data-kind="visitor" data-id="${safe(x.id)}" data-value="left">Check out visitor</button>`;
  if(kind==='checkin'&&x.state==='pending'&&allowed('decision:checkin'))buttons=`<button class="button primary" data-action="decision" data-kind="checkin" data-id="${safe(x.id)}" data-value="verified">Verify field visit</button>`;
  if(kind==='qc'&&x.state==='scheduled'&&allowed('decision:qc'))buttons=`<button class="button primary" data-action="decision" data-kind="qc" data-id="${safe(x.id)}" data-value="passed">Complete inspection</button>`;
 }
 modal(kind==='order'?x.id+' · Production workspace':x.id+' · Record detail','Mock management software record · all changes stay in this browser.',body,`<div class="modal-actions"><button class="button" data-action="close">Close</button>${buttons}</div>`);
}
function exportCSV(){let list=onlyBuyer(data.orders);let rows=[['Order','Buyer','Style','Factory','Quantity','Stage','Progress','Delivery','Merchandiser'],...list.map(o=>[o.id,o.buyer,o.style,o.factory,o.qty,o.status,o.progress,o.due,o.owner])];let csv=rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='ensa-software-demo-orders.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Demo CSV export downloaded')}
function action(cmd,el){if(cmd==='close'){$('#modal').innerHTML='';return}if(cmd==='switch-user'){modal('Switch user dashboard','Select any role to preview its full workspace and navigation.',`<div class="user-picker">${Object.entries(ROLES).map(([k,r])=>`<button type="button" class="user-option ${k===role?'current':''}" data-role="${k}"><span class="picker-icon">${r.initials}</span><span class="picker-copy"><b>${r.name}</b><small>${r.user} · ${r.caption}</small></span><span class="picker-end">${k===role?'✓':'›'}</span></button>`).join('')}</div>`);return}if(cmd==='activity'){if(role!=='executive'){go('dashboard');return}modal('Company activity','Updates across orders, QC, finance, HR, attendance and reception.',ceoFeed(8));return}if(['new-order','new-sample','new-qc','new-visitor','new-expense','new-leave'].includes(cmd)){formModal(cmd);return}if(PAGES[cmd]){go(cmd);return}if(cmd==='export'){exportCSV();return}if(cmd==='advance'){const o=data.orders.find(x=>x.id===el.dataset.id);if(o){o.progress=Math.min(100,o.progress+10);o.status=o.progress===100?'shipped':'production';persist();$('#modal').innerHTML='';render();toast('Order progress updated')}return}if(cmd==='decision'){let collection={sample:'samples',qc:'inspections',leave:'leaves',expense:'expenses',visitor:'visitors',checkin:'checkins'}[el.dataset.kind];let x=data[collection]?.find(t=>t.id===el.dataset.id);if(x){x.state=el.dataset.value;persist();$('#modal').innerHTML='';render();toast('Demo record updated successfully')}return}if(cmd==='checkin'){const now=new Date(),time=now.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'});let x={id:'AT-'+Date.now().toString().slice(-5),name:ROLES[role].user,type:'Factory QC',place:'Factory location not verified',time,state:'pending'};data.checkins.unshift(x);persist();toast('Mock check-in recorded. GPS not collected; management review pending.');go('attendance');return}if(cmd==='qc-report'){modal('QC report preview','Factory inspection report workflow',`<div class="notice">The full product would capture inspection checklists, evidence, defects and corrective actions. This mock screen does not upload actual factory evidence.</div>`, `<div class="modal-actions"><button class="button primary" data-action="close">Got it</button></div>`);return}if(cmd==='payroll'||cmd==='invite'||cmd==='add-partner'||cmd==='appointments'){modal({payroll:'Payroll summary preview',invite:'User invitation preview','add-partner':'Partner registration preview',appointments:'Appointment calendar preview'}[cmd],'This is a mock workflow in the static design.',`<div class="notice">This action is included in the proposed ERP scope as a visual concept. A production version would require authenticated records, validation, and a backend.</div>`,`<div class="modal-actions"><button class="button primary" data-action="close">Close</button></div>`);return}}
const unguardedAction=action;
action=function(cmd,el){
 const requirement=cmd==='decision'?'decision:'+el?.dataset.kind:cmd;
 if(!allowed(requirement))return toast('This action is assigned to another user role.');
 if(cmd==='qc-report'){
  const options=data.inspections.filter(i=>role!=='qc'||i.inspector===ROLES.qc.user).map(i=>`<option value="${safe(i.id)}">${safe(i.id)} · ${safe(i.factory)}</option>`).join('');
  modal('Submit inspection findings','Record a factory visit result. This is a fictional demonstration.',`<form id="demoForm" data-type="qc-report"><div class="form-grid"><div class="field full"><label>Inspection</label><select name="id" required>${options}</select></div><div class="field"><label>Result</label><select name="result"><option value="passed">Passed</option><option value="attention">Needs corrective action</option></select></div><div class="field"><label>Inspection score</label><input name="score" type="number" min="0" max="100" required value="92"></div><div class="field full"><label>Findings and follow-up</label><textarea name="note" rows="3" required placeholder="Summary of observations and required action"></textarea></div></div><div class="modal-actions"><button type="button" class="button" data-action="close">Cancel</button><button type="submit" class="button primary">Submit report</button></div></form>`);
  return;
 }
 if(cmd==='decision'&&role==='buyer'){
  const sample=data.samples.find(s=>s.id===el?.dataset.id);
  if(el?.dataset.kind!=='sample'||!sample||sample.buyer!=='H&M Group')return toast('This approval is not assigned to your buyer account.');
 }
 if(cmd==='advance'&&role==='merch'){
  const order=data.orders.find(o=>o.id===el?.dataset.id);
  if(!order||order.owner!==ROLES.merch.user)return toast('Only your assigned orders can be updated.');
 }
 unguardedAction(cmd,el);
 if(cmd==='advance')logActivity('Production progress changed',`${el.dataset.id} was updated by ${ROLES[role].user}.`,'Order management','orders','▤');
 if(cmd==='decision'){
  const teams={sample:'Buyer approvals',qc:'Quality control',leave:'Human resources',expense:'Finance',visitor:'Reception',checkin:'Field attendance'};
  const modules={sample:'samples',qc:'quality',leave:'hr',expense:'finance',visitor:'reception',checkin:'attendance'};
  logActivity('Record '+el.dataset.value,`${el.dataset.id} updated by ${ROLES[role].user}.`,teams[el.dataset.kind],modules[el.dataset.kind],'✓');
 }
 if(cmd==='checkin')logActivity('Factory visit check-in','A QC field check-in was submitted for verification.','Factory attendance','attendance','◷');
};
document.addEventListener('click',e=>{let r=e.target.closest('[data-role]');if(r){switchRole(r.dataset.role);return}let p=e.target.closest('[data-page]');if(p){go(p.dataset.page);return}let row=e.target.closest('[data-kind][data-id]');if(row){detail(row.dataset.kind,row.dataset.id);return}let b=e.target.closest('[data-action]');if(b){action(b.dataset.action,b);return}if(e.target.classList.contains('modal-backdrop'))$('#modal').innerHTML=''});
document.addEventListener('change',e=>{if(e.target.id==='roleSelect')switchRole(e.target.value);if(e.target.id==='filterOrders'){filter=e.target.value;render()} });
document.addEventListener('input',e=>{if(e.target.id==='searchOrders'){search=e.target.value;let current=document.activeElement,position=current.selectionStart;const list=onlyBuyer(data.orders).filter(o=>(`${o.id} ${o.style} ${o.buyer} ${o.factory} ${o.owner}`).toLowerCase().includes(search.toLowerCase())&&(filter==='all'||o.status===filter));const outer=$('#main .filters + .card');if(outer){outer.querySelector('.table-scroll').outerHTML=orderRows(list);let p=outer.querySelector('.card-head p');if(p)p.textContent=`${list.length} matching orders · select a row for milestones`}}});
document.addEventListener('submit',e=>{
 if(e.target.id!=='demoForm')return;
 e.preventDefault();
 const type=e.target.dataset.type;
 if(!allowed(type))return toast('You cannot create this record in the selected role.');
 const f=new FormData(e.target),val=k=>String(f.get(k)||'').trim();
 const date=s=>{let d=new Date(s+'T12:00:00');return Number.isNaN(d.getTime())?'TBD':d.toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'})};
 const id=Date.now().toString().slice(-6);
 if(type==='qc-report'){
  const inspection=data.inspections.find(i=>i.id===val('id'));
  if(!inspection||role==='qc'&&inspection.inspector!==ROLES.qc.user)return toast('Inspection not assigned to this role.');
  inspection.state=val('result');inspection.score=Number(val('score'));inspection.note=val('note');
  logActivity('QC inspection report submitted',`${inspection.id} · ${inspection.factory} · ${inspection.state} · ${inspection.score}/100.`, 'Quality control','quality','◎');
  $('#modal').innerHTML='';go('quality');toast('Mock inspection report saved');return;
 }
 if(type==='new-order')data.orders.unshift({id:'EN-'+id,buyer:val('buyer'),style:val('style'),factory:val('factory'),qty:Number(val('qty')),progress:0,status:'sampling',due:date(val('due')),owner:val('owner'),value:0});
 if(type==='new-sample'){let o=data.orders.find(o=>o.id===val('order'));data.samples.unshift({id:'S-'+id,buyer:o?.buyer||'',order:val('order'),type:val('type'),state:'pending',date:'Today',note:val('note')})}
 if(type==='new-qc')data.inspections.unshift({id:'QC-'+id,factory:val('factory'),order:val('order'),inspector:val('inspector'),date:date(val('date')),state:'scheduled',score:0});
 if(type==='new-visitor')data.visitors.unshift({id:'VS-'+id,name:val('name'),company:val('company'),host:val('host'),time:new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}),state:'inside'});
 if(type==='new-expense')data.expenses.unshift({id:'EX-'+id,type:val('type'),order:val('order'),amount:Number(val('amount')),state:'pending'});
 if(type==='new-leave')data.leaves.unshift({id:'LV-'+id,name:val('name'),type:val('type'),days:val('days'),state:'pending'});
 const module={"new-order":"orders","new-sample":"samples","new-qc":"quality","new-visitor":"reception","new-expense":"finance","new-leave":"hr"}[type];
 logActivity('New record created',`${type.replace('new-','')} record created by ${ROLES[role].user}.`,ROLES[role].name,module,'＋');
 $('#modal').innerHTML='';render();toast('New demo record created');
});
document.addEventListener('click',e=>{let t=e.target.closest('[data-tab]');if(t){tab=t.dataset.tab;render()}});
$('#menuBtn').addEventListener('click',()=>{$('#sidebar').classList.add('open');$('#backdrop').classList.add('visible')});$('#closeSidebar').addEventListener('click',closeMenu);$('#backdrop').addEventListener('click',closeMenu);$('#searchBtn').addEventListener('click',()=>{if(ROLES[role].nav.includes('orders')){go('orders');$('#searchOrders')?.focus()}else toast('Search is available in the relevant module.')});$('#bellBtn').addEventListener('click',()=>toast('3 operational alerts are included in this demonstration.'));document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#modal').innerHTML='';closeMenu()}});
$('#mobileMore').addEventListener('click',()=>{$('#sidebar').classList.add('open');$('#backdrop').classList.add('visible')});document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#modal').innerHTML='';closeMenu()}});
render();
